def ts(s):
    return f"{int(s//3600):02d}:{int(s//60)%60:02d}:{int(s%60):02d},{int((s%1)*1000):03d}"
out=[];idx=1
for no,title,start,end in scenes:
    ls=lines[no]; slot=(end-start)/len(ls); t=start
    for l in ls:
        out.append(f"{idx}\n{ts(t)} --> {ts(min(t+slot-0.3,end))}\n{l}\n"); idx+=1; t+=slot
open("film/2035-ai-takes-control/subtitles/subtitles-hi.srt","w",encoding="utf-8").write("\n".join(out))
# storyboard
shots=["Extreme wide aerial establishing","Slow push-in wide","Over-the-shoulder dialogue","Emotional close-up","Insert — key object/screen","Tracking shot","Low-angle hero shot","Reaction close-up"]
loc={1:"Mumbai skyline / streets, 2:17 AM, rain",2:"AI research center, day-evening",3:"Aanaya apartment, night",4:"Hospital ICU",5:"Aanaya apartment, archive",6:"Corporate HQ, rain",7:"AI diagnostic room",8:"Underground maintenance tunnel",9:"Underground tunnel, closing door",10:"Manual control room, countdown",11:"Across Mumbai — montage",12:"Central control room",13:"Mumbai sunrise / hospital"}
with open("film/2035-ai-takes-control/storyboard-shot-list.csv","w",newline="",encoding="utf-8") as f:
    w=csv.writer(f); w.writerow(["shot_id","scene","timecode_in","timecode_out","duration_sec","shot_type","location","characters","action_dialogue_beat","camera","lighting_act"])
    n=0
    for no,title,start,end in scenes:
        dur=end-start; per=dur/7
        for i in range(7):
            n+=1; s=start+i*per
            w.writerow([f"S{no:02d}-{i+1}",f"{no}. {title}",ts(s)[:8],ts(s+per)[:8],round(per,1),shots[(i+no)%len(shots)],loc[no],"Aanaya/NIRA/Sameer per screenplay",lines[no][min(i,len(lines[no])-1)][:80],"Locked geography, 180-degree rule; motivated move only","Act 1 blue" if no<=3 else ("Act 2 red" if no<=7 else ("Act 3 purple" if no<=12 else "Golden sunrise"))])
words=sum(len(re.findall(r'\S+',l)) for v in lines.values() for l in v)
print("cues",idx-1,"spoken_words_approx",words,"total_sec",810,"shots",n)
